package com.abhiai.abhiai_backend.entity;import java.time.Instant;import java.util.UUID;import org.hibernate.annotations.CreationTimestamp;import jakarta.persistence.*;@Entity@Table(name="moderation_audit_logs")public class ModerationAuditLog{@Id@GeneratedValue(strategy=GenerationType.UUID)private UUID id;@Column(name="administrator_email",nullable=false,length=254)private String email;@Column(nullable=false,length=32)private String action;@Column(name="target_type",nullable=false,length=32)private String targetType;@Column(name="target_id",nullable=false)private UUID targetId;@Column(nullable=false,length=1000)private String reason;@CreationTimestamp@Column(name="created_at",nullable=false,updatable=false)private Instant createdAt;protected ModerationAuditLog(){}public ModerationAuditLog(String e,String a,String t,UUID id,String r){email=e;action=a;targetType=t;targetId=id;reason=r;}}
